let v=$input.first().json.choices?.[0]?.message?.content;
if(typeof v==='string'){v=v.replace(/^```(?:json)?\s*|\s*```$/g,'');v=JSON.parse(v)}
if(!v||!Array.isArray(v.options)||v.options.length!==2)throw new Error('Groq must return exactly two options');
const sources=$('Clean research').first().json.sources;const allowed=new Set(sources.map(s=>s.url));
for(const o of v.options){for(const k of ['angle','linkedin','x','image_prompt'])if(typeof o[k]!=='string'||!o[k].trim())throw new Error('Missing draft field '+k);if([...o.x].length>280)throw new Error('X draft exceeds 280 characters');if(!Array.isArray(o.source_urls)||!o.source_urls.some(url=>allowed.has(url)))throw new Error('Draft lacks a valid source URL');}
const q=$('Pick one topic').first().json;
return [{json:{...q,sources,options:v.options.map(o=>({angle:o.angle,linkedin:o.linkedin,x:o.x,image_prompt:o.image_prompt,source_urls:o.source_urls.filter(url=>allowed.has(url))})),seeds:[Math.floor(Math.random()*1000000000),Math.floor(Math.random()*1000000000)]}}];

const c = $input.first().json.callback_query;
if (!c) return [];

const match = /^content\|(A|B|R|S)\|([A-Za-z0-9_-]{1,40})\|([0-9]{1,10})$/.exec(String(c.data || ''));

if (
  !match ||
  String(c.message?.chat?.id) !== String($('Callback config').first().json.telegram_chat_id)
) return [];

return [{
  json: {
    action: match[1],
    topic_id: match[2],
    review_id: match[3],
    callback_id: c.id,
    chat_id: String(c.message.chat.id)
  }
}];;

const row = $input.first()?.json || {};
const c = $('Validate callback').first().json;

if (
  String(row.topic_id) !== c.topic_id ||
  String(row.status).trim().toLowerCase() !== 'awaiting_approval' ||
  String(row.review_id) !== c.review_id
) return [];

return [{ json: { ...c, row } }];

const c = $('Check pending choice').first().json;

let draft;
try {
  draft = JSON.parse(c.action === 'A' ? c.row.draft_a : c.row.draft_b);
} catch {
  throw new Error('Missing saved draft');
}

const telegram_file_id =
  c.action === 'A' ? c.row.telegram_file_id_a : c.row.telegram_file_id_b;

if (!draft.linkedin || !draft.x || !telegram_file_id) {
  throw new Error('Selected post or preview image is missing');
}

return [{
  json: {
    topic_id: c.topic_id,
    chosen: c.action,
    linkedin: draft.linkedin,
    x: draft.x,
    telegram_file_id
  }
}];

const p=$input.first().json;const c=$('Prepare selected post').first().json;
const urn=p.urn||p.id||p.postId||'';
if(!urn)throw new Error('LinkedIn did not return a post ID; inspect node output before retrying');
const linkedin_url=urn.startsWith('http')?urn:'https://www.linkedin.com/feed/update/'+encodeURIComponent(urn);
return [{json:{...c,linkedin_url}}];
